from itertools import combinations
from random import Random


def _decimal_parts(token: str) -> tuple[bool, str] | None:
    negative = token.startswith("-")
    digits = token[1:] if token.startswith(("+", "-")) else token
    if not digits or not digits.isascii() or not digits.isdecimal():
        return None
    digits = digits.lstrip("0") or "0"
    return negative and digits != "0", digits


def _parse_input(inp: str) -> tuple[int, list[tuple[int, int, int]]] | None:
    tokens = inp.split()
    if not 5 <= len(tokens) <= 15002:
        return None
    values = []
    for token in tokens:
        parts = _decimal_parts(token)
        if parts is None:
            return None
        negative, digits = parts
        if negative or len(digits) > 6:
            return None
        values.append(int(digits))

    count, budget = values[:2]
    if not (1 <= count <= 5000 and 1 <= budget <= 5000):
        return None
    if len(values) != 2 + 3 * count:
        return None

    foods = []
    for offset in range(2, len(values), 3):
        vitamin, amount, calories = values[offset:offset + 3]
        if not (1 <= vitamin <= 3 and 1 <= amount <= 200000):
            return None
        if not 1 <= calories <= budget:
            return None
        foods.append((vitamin, amount, calories))
    return budget, foods


def _format_input(budget: int, foods: list[tuple[int, int, int]]) -> str:
    lines = [f"{len(foods)} {budget}"]
    lines.extend(f"{vitamin} {amount} {calories}"
                 for vitamin, amount, calories in foods)
    return "\n".join(lines) + "\n"


def validate_input(inp: str) -> bool:
    return _parse_input(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = Random(seed)
    cases = [
        (1, [(1, 1, 1)]),
        (3, [(1, 9, 1), (2, 7, 1), (3, 5, 1)]),
        (2, [(1, 9, 1), (2, 7, 1), (3, 5, 1)]),
        (5000, [(1, 200000, 1), (2, 200000, 1)]),
        (6, [(1, 4, 1), (1, 4, 1), (2, 8, 2), (3, 8, 2)]),
        (7, [(1, 200000, 7), (1, 4, 2), (2, 8, 2), (3, 5, 2)]),
        (10, [(1, 3, 1), (2, 7, 2), (3, 5, 3), (1, 4, 4)]),
        (25, [(1, 8, 5), (2, 3, 5), (2, 7, 10), (3, 2, 5), (3, 3, 10)]),
    ]
    result = [_format_input(budget, foods) for budget, foods in cases[:max(0, n)]]
    while len(result) < n:
        budget = rng.choice((rng.randint(1, 30), 5000))
        foods = [
            (
                rng.randint(1, 3),
                rng.choice((1, rng.randint(2, 50), 200000)),
                rng.choice((1, rng.randint(1, min(12, budget)), budget)),
            )
            for _ in range(rng.randint(1, 8))
        ]
        result.append(_format_input(budget, foods))
    return result


def gen_stress(seed: int) -> list[str]:
    rng = Random(seed)
    budget = 5000
    low_cost = [
        (1 + i % 3, rng.randint(1, 200000), rng.randint(2, 5))
        for i in range(5000)
    ]
    mixed_cost = [
        (1 + i % 3, rng.randint(1, 200000), 1 + i % 5000)
        for i in range(5000)
    ]
    rng.shuffle(low_cost)
    rng.shuffle(mixed_cost)
    return [_format_input(budget, low_cost), _format_input(budget, mixed_cost)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    parsed = _parse_input(inp)
    if parsed is None:
        return [("POST-1", "The input violates the format or value bounds.")]
    budget, foods = parsed
    tokens = out.split()
    if len(tokens) != 1:
        return [("POST-2", "Expected exactly one integer token.")]
    parts = _decimal_parts(tokens[0])
    if parts is None:
        return [("POST-2", "The output token is not a decimal integer.")]

    totals = [0, 0, 0]
    cheapest = [budget + 1] * 3
    total_calories = 0
    for vitamin, amount, calories in foods:
        index = vitamin - 1
        totals[index] += amount
        cheapest[index] = min(cheapest[index], calories)
        total_calories += calories

    tightest_supply = min(totals)
    upper = min(tightest_supply, 200000 * (min(len(foods), budget) // 3))
    negative, digits = parts
    if negative or len(digits) > len(str(upper)):
        return [("POST-3", f"The answer must lie between 0 and {upper}.")]

    answer = int(digits)
    failures = []
    if answer > upper:
        failures.append(("POST-3", f"The answer exceeds the upper bound {upper}."))
    if (answer == 0) != (sum(cheapest) > budget):
        failures.append(("POST-4", "The answer must be positive exactly when all three vitamin types fit."))
    if total_calories <= budget and answer != tightest_supply:
        failures.append(("POST-5", "All foods fit, so the smallest total vitamin supply is attainable."))
    return failures


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = Random(seed)
    pairs = []
    for index in range(n):
        budget = rng.randint(3, 40)
        foods = [
            (1 + i % 3, rng.randint(1, 1000), rng.randint(1, min(budget, 8)))
            for i in range(rng.randint(3, 8))
        ]
        rng.shuffle(foods)
        original = _format_input(budget, foods)
        relation = "equal"
        change = index % 5
        if change == 0:
            transformed = _format_input(budget, foods[::-1])
        elif change == 1:
            relabeled = [(vitamin % 3 + 1, amount, cost)
                         for vitamin, amount, cost in foods]
            transformed = _format_input(budget, relabeled)
        elif change == 2:
            relation = "le"
            transformed = _format_input(budget + rng.randint(1, 20), foods)
        elif change == 3:
            relation = "le"
            chosen = rng.randrange(len(foods))
            vitamin, amount, cost = foods[chosen]
            foods[chosen] = (vitamin, amount + rng.randint(1, 1000), cost)
            transformed = _format_input(budget, foods)
        else:
            relation = "le"
            foods.append((rng.randint(1, 3), rng.randint(1, 200000), 1))
            transformed = _format_input(budget, foods)
        pairs.append(("POST-6", relation, original, transformed))
    return pairs


def reference_small(inp: str) -> str | None:
    parsed = _parse_input(inp)
    if parsed is None:
        return None
    budget, foods = parsed
    if len(foods) > 12:
        return None

    best = 0
    for size in range(len(foods) + 1):
        for subset in combinations(foods, size):
            if sum(calories for _, _, calories in subset) <= budget:
                intake = [0, 0, 0]
                for vitamin, amount, _ in subset:
                    intake[vitamin - 1] += amount
                best = max(best, min(intake))
    return f"{best}\n"
